<script setup lang="ts">import { computed, onBeforeUnmount, onMounted, ref } from "vue"; import { useRoute, useRouter } from "vue-router"; import type { GameDetail, GameLaunchState, GameLaunchStateResponse } from "@arcade/shared"; import { getPortalGame, requestGameLaunch, sendAnalyticsEvents } from "../services/api"; import { rememberRecent } from "../services/portalStorage"; import LaunchProgressPanel from "../components/portal/LaunchProgressPanel.vue"; import ContentStatePanel from "../components/portal/ContentStatePanel.vue";
const route = useRoute(); const router = useRouter(); const slug = String(route.params.slug); const game = ref<GameDetail | null>(null); const state = ref<GameLaunchState>("requested"); const message = ref(""); const launch = ref<GameLaunchStateResponse | null>(null); const iframe = ref<HTMLIFrameElement | null>(null); const elapsed = ref(0); const isOnline = ref(true); let timer = 0; const progressTitle = computed(() => game.value ? `${game.value.title} · 启动` : "启动游戏");
function validMessage(event: MessageEvent<unknown>): boolean { if (!launch.value || !iframe.value || event.source !== iframe.value.contentWindow || (launch.value.allowed_origin && event.origin !== launch.value.allowed_origin)) return false; const data = event.data as Record<string, unknown> | null; return Boolean(data && ["game_ready", "game_progress", "game_exit", "game_resize", "game_error"].includes(String(data.type)) && data.game_id === launch.value.game_id && data.release_id === launch.value.release_id && data.schema_version === 1); }
function onMessage(event: MessageEvent<unknown>): void { if (!validMessage(event)) return; const data = event.data as Record<string, unknown>; if (data.type === "game_ready") state.value = "running"; if (data.type === "game_progress" && typeof data.progress === "number") elapsed.value = Math.min(100, Math.max(0, data.progress)); if (data.type === "game_exit") void router.push(`/zh/game/${slug}`); if (data.type === "game_error") { state.value = "failed"; message.value = "游戏报告资源错误，请重试或返回详情。"; } }
async function start(): Promise<void> { state.value = "requested"; message.value = ""; elapsed.value = 0; try { state.value = "validating"; const data = await requestGameLaunch(slug); launch.value = data; state.value = data.state; message.value = data.message || ""; if (data.state === "blocked" || data.state === "paused" || data.state === "offline" || data.state === "failed") return; if (!data.launch_url || !data.release_id) { state.value = "blocked"; message.value = "服务端没有返回有效 release 和启动配置，平台不会猜测游戏地址。"; return; } if (data.launch_mode === "new-window") { window.open(data.launch_url, "_blank", "noopener,noreferrer"); state.value = "running"; return; } state.value = "preparing"; rememberRecent(slug); await sendAnalyticsEvents([{ event_name: "launch_validated", game_id: data.game_id, release_id: data.release_id, route: route.fullPath, schema_version: 1 }]); state.value = "loading"; } catch { state.value = navigator.onLine ? "failed" : "offline"; message.value = "启动请求失败，请检查网络后重试。"; } }
function back(): void { void router.push(`/zh/game/${slug}`); } function retry(): void { void start(); } async function fullscreen(): Promise<void> { try { await document.documentElement.requestFullscreen(); } catch { message.value = "浏览器未允许全屏，请使用系统全屏操作。"; } }
function onOnline(): void { isOnline.value = true; if (state.value === "offline") message.value = "网络已恢复，可以重试启动。"; } function onOffline(): void { isOnline.value = false; if (state.value !== "running") state.value = "offline"; } onMounted(async () => { isOnline.value = navigator.onLine; window.addEventListener("message", onMessage); window.addEventListener("online", onOnline); window.addEventListener("offline", onOffline); try { game.value = await getPortalGame(slug); document.title = `${game.value.title} · 启动｜星屿游廊`; await start(); } catch { state.value = "failed"; message.value = "无法读取游戏详情。"; } }); onBeforeUnmount(() => { window.removeEventListener("message", onMessage); window.removeEventListener("online", onOnline); window.removeEventListener("offline", onOffline); window.clearTimeout(timer); });
</script><template><div class="launch-page"><header class="launch-header"><button type="button" class="launch-back" @click="back">‹</button><div><span class="portal-eyebrow">SECURE LAUNCH</span><strong>{{ progressTitle }}</strong></div><span class="launch-network">{{ isOnline ? "在线" : "离线" }}</span></header><LaunchProgressPanel :state="state" :message="message" @back="back" @retry="retry" @fullscreen="fullscreen" /><section v-if="state === 'loading' || state === 'ready' || state === 'running'" class="game-runtime"><iframe v-if="launch?.launch_mode === 'iframe' && launch.launch_url" ref="iframe" :src="launch.launch_url" title="受控游戏窗口" sandbox="allow-scripts allow-pointer-lock allow-forms"></iframe><div v-else-if="launch?.launch_mode === 'same-origin' && launch.launch_url" class="same-origin-runtime"><p>同站游戏资源已准备，等待容器响应。</p></div><ContentStatePanel v-else kind="blocked" title="无法打开游戏容器" message="服务端没有返回可验证的受控启动地址。" /></section><p class="launch-timeout-note">超过 8 秒仍未完成时，请检查网络并重试；超过 30 秒仍失败，请返回详情页。</p></div></template>
